<template>
  <div class="count-page">
    <div class="page-header"><div><h2>库存盘点</h2><p>按账面快照执行初盘、复盘和差异审核，确认后自动生成盘盈/盘亏流水</p></div><div><el-button @click="$router.push('/warehouse')">返回库存台账</el-button><el-button type="primary" @click="openCreate">新建盘点单</el-button></div></div>
    <el-alert type="warning" :closable="false" show-icon title="盘点确认前会再次校验库存是否发生异动；存在未盘、超阈值未复盘或未填写差异原因时禁止确认。"/>
    <div class="metrics"><el-card><span>盘点单</span><b>{{rows.length}}</b></el-card><el-card><span>盘点中</span><b>{{rows.filter(r=>['draft','counting','recounting'].includes(r.status)).length}}</b></el-card><el-card><span>待复盘差异</span><b class="warning">{{rows.reduce((s,r)=>s+r.difference_count,0)}}</b></el-card><el-card><span>平均准确率</span><b class="ok">{{averageAccuracy}}%</b></el-card></div>
    <el-card class="panel"><div class="filters"><el-date-picker v-model="dateRange" type="daterange" value-format="YYYY-MM-DD" range-separator="至" :clearable="false"/><el-select v-model="statusFilter" clearable placeholder="全部状态"><el-option v-for="(label,key) in statuses" :key="key" :label="label" :value="key"/></el-select><el-button type="primary" @click="loadCounts">查询</el-button></div>
      <el-table :data="rows" stripe><el-table-column prop="count_no" label="盘点单号" min-width="190"/><el-table-column prop="warehouse" label="仓库" width="110"/><el-table-column label="类型" width="100"><template #default="s">{{typeName(s.row.count_type)}}</template></el-table-column><el-table-column prop="planned_start" label="计划开始" width="170"><template #default="s">{{datetime(s.row.planned_start)}}</template></el-table-column><el-table-column prop="responsible_name" label="负责人" width="100"/><el-table-column label="进度" width="150"><template #default="s">{{s.row.counted_count}} / {{s.row.item_count}}</template></el-table-column><el-table-column label="差异" width="120"><template #default="s"><span :class="{danger:s.row.difference_count}">{{s.row.difference_count}} 项</span></template></el-table-column><el-table-column label="准确率" width="100"><template #default="s">{{s.row.accuracy_rate}}%</template></el-table-column><el-table-column label="状态" width="100"><template #default="s"><el-tag :type="statusTag(s.row.status)">{{statuses[s.row.status]||s.row.status}}</el-tag></template></el-table-column><el-table-column label="操作" width="220" fixed="right"><template #default="s"><el-button link type="primary" @click="openDetail(s.row)">盘点录入</el-button><el-button link @click="downloadReport(s.row)">差异表</el-button></template></el-table-column></el-table>
    </el-card>

    <el-dialog v-model="createVisible" title="新建盘点单" width="860px"><el-form label-width="110px"><el-row :gutter="14"><el-col :span="8"><el-form-item label="盘点仓库" required><el-select v-model="form.warehouse" style="width:100%"><el-option v-for="w in options.warehouses" :key="w" :label="w" :value="w"/></el-select></el-form-item></el-col><el-col :span="8"><el-form-item label="盘点类型"><el-select v-model="form.count_type" style="width:100%"><el-option label="全仓盘点" value="full"/><el-option label="范围盘点" value="partial"/><el-option label="循环盘点" value="cycle"/></el-select></el-form-item></el-col><el-col :span="8"><el-form-item label="差异复盘阈值"><el-input-number v-model="form.difference_threshold" :min="0" :max="100"/><span>%</span></el-form-item></el-col></el-row>
      <el-form-item label="计划时间" required><el-date-picker v-model="form.planRange" type="datetimerange" value-format="YYYY-MM-DDTHH:mm:ss" range-separator="至" start-placeholder="开始" end-placeholder="结束" style="width:100%"/></el-form-item>
      <el-row :gutter="14"><el-col :span="12"><el-form-item label="负责人" required><el-select v-model="form.responsible_id" filterable style="width:100%"><el-option v-for="u in options.users" :key="u.id" :label="u.name" :value="u.id"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="参与人员"><el-select v-model="form.participant_ids" multiple filterable style="width:100%"><el-option v-for="u in options.users" :key="u.id" :label="u.name" :value="u.id"/></el-select></el-form-item></el-col></el-row>
      <el-divider>盘点范围（可组合）</el-divider><el-row :gutter="14"><el-col :span="12"><el-form-item label="商品分类"><el-select v-model="form.scope.categories" multiple clearable style="width:100%"><el-option v-for="v in options.categories" :key="v" :label="v" :value="v"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="ABC等级"><el-select v-model="form.scope.abc_levels" multiple clearable style="width:100%"><el-option label="A 畅销/重点" value="A"/><el-option label="B 平销" value="B"/><el-option label="C 滞销" value="C"/></el-select></el-form-item></el-col></el-row>
      <el-row :gutter="14"><el-col :span="12"><el-form-item label="指定商品"><el-select v-model="form.scope.product_ids" multiple filterable collapse-tags style="width:100%"><el-option v-for="p in options.products" :key="p.id" :label="`${p.sku||'无编码'} · ${p.name}`" :value="p.id"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="供应商批次"><el-select v-model="form.scope.supplier_ids" multiple filterable style="width:100%"><el-option v-for="s in options.suppliers" :key="s.id" :label="s.name" :value="s.id"/></el-select></el-form-item></el-col></el-row>
      <el-form-item label="临期商品"><el-switch v-model="form.scope.near_expiry_only"/><span class="hint">仅盘点临期/过期批次；临期阈值</span><el-input-number v-model="form.scope.near_expiry_days" :min="1" :max="365"/> 天</el-form-item>
      </el-form><template #footer><el-button @click="createVisible=false">取消</el-button><el-button type="primary" :loading="saving" @click="create">生成盘点任务</el-button></template></el-dialog>

    <el-dialog v-model="detailVisible" :title="detail.count_no ? `盘点录入 · ${detail.count_no}` : '盘点录入'" width="96%" top="2vh" destroy-on-close><div class="detail-head"><div><el-tag>{{statuses[detail.status]}}</el-tag><span>账面快照 {{detail.item_count}} 项，已盘 {{detail.counted_count}} 项，差异 {{detail.difference_count}} 项</span></div><div><el-button @click="downloadTemplate">下载录入模板</el-button><el-upload :show-file-list="false" :http-request="uploadCount" accept=".xlsx"><el-button>导入盘点结果</el-button></el-upload><el-button type="warning" :disabled="!selectedItems.length" @click="recount">生成复盘</el-button><el-button type="success" :disabled="detail.status==='confirmed'" @click="confirm">确认差异并记账</el-button></div></div>
      <el-table ref="detailTable" :data="detail.items" row-key="id" border height="610" @selection-change="selectedItems=$event"><el-table-column type="selection" width="45"/><el-table-column prop="sku" label="编码" width="110"/><el-table-column prop="product_name" label="商品" min-width="150"/><el-table-column prop="category" label="分类" width="100"/><el-table-column prop="abc_level" label="ABC" width="65"/><el-table-column prop="location" label="库位" width="100"/><el-table-column label="批次号" width="130"><template #default="s"><el-input v-model="s.row.batch_no" :disabled="detail.status==='confirmed'"/></template></el-table-column><el-table-column label="生产日期" width="145"><template #default="s"><el-date-picker v-model="s.row.production_date" value-format="YYYY-MM-DD" :disabled="detail.status==='confirmed'" style="width:130px"/></template></el-table-column><el-table-column label="保质期" width="105"><template #default="s"><el-input-number v-model="s.row.shelf_life_days" :min="1" :controls="false" :disabled="detail.status==='confirmed'" style="width:88px"/></template></el-table-column><el-table-column label="批次状态" width="105"><template #default="s"><el-tag :type="s.row.batch_status==='expired'?'danger':s.row.batch_status==='near_expiry'?'warning':'info'">{{batchStatus(s.row.batch_status)}}</el-tag></template></el-table-column><el-table-column label="账面数" width="105"><template #default="s">{{number(s.row.system_quantity)}} {{s.row.unit_name}}</template></el-table-column><el-table-column label="实盘数" width="135"><template #default="s"><el-input-number class="actual-input" v-model="s.row.actual_quantity" :min="0" :precision="4" :controls="false" :disabled="detail.status==='confirmed'" @keyup.enter="focusNext" style="width:115px"/></template></el-table-column><el-table-column label="差异数" width="100"><template #default="s"><b :class="differenceClass(s.row)">{{number(currentDifference(s.row))}}</b></template></el-table-column><el-table-column label="差异金额" width="115"><template #default="s">¥{{money(currentDifference(s.row)*s.row.avg_cost)}}</template></el-table-column><el-table-column label="差异原因" width="160"><template #default="s"><el-select v-model="s.row.difference_reason" clearable :disabled="detail.status==='confirmed'"><el-option v-for="r in options.difference_reasons" :key="r" :label="r" :value="r"/></el-select></template></el-table-column><el-table-column label="说明" min-width="170"><template #default="s"><el-input v-model="s.row.reason_note" :disabled="detail.status==='confirmed'"/></template></el-table-column><el-table-column label="复盘" width="90"><template #default="s"><el-tag v-if="s.row.recount_required" type="warning">{{s.row.recount_quantity==null?'待复盘':'已复盘'}}</el-tag></template></el-table-column></el-table>
      <template #footer><el-button @click="detailVisible=false">关闭</el-button><el-button v-if="detail.status!=='confirmed'" type="primary" :loading="saving" @click="saveEntries">保存盘点结果</el-button></template></el-dialog>
  </div>
</template>

<script setup>
import { computed,onMounted,reactive,ref } from 'vue'
import { ElMessage,ElMessageBox } from 'element-plus'
import { confirmInventoryCount,createInventoryCount,createInventoryRecount,downloadInventoryCountTemplate,exportInventoryCount,getInventoryCount,getInventoryCounts,getWarehouseOptions,importInventoryCount,saveInventoryCountEntries } from '@/api'
const today=()=>new Date().toLocaleDateString('sv-SE'), datetime=v=>v?new Date(v).toLocaleString('zh-CN',{hour12:false}):'—'
const statuses={draft:'待盘点',counting:'盘点中',recounting:'复盘中',confirmed:'已确认',cancelled:'已取消'}
const rows=ref([]),dateRange=ref([today(),today()]),statusFilter=ref(null),createVisible=ref(false),detailVisible=ref(false),saving=ref(false),selectedItems=ref([])
const options=reactive({products:[],users:[],suppliers:[],warehouses:['主仓库'],categories:[],difference_reasons:[]}),detail=reactive({items:[]})
const defaultRange=()=>{const start=new Date(),end=new Date(Date.now()+2*3600000);const fmt=d=>`${d.toLocaleDateString('sv-SE')}T${d.toTimeString().slice(0,8)}`;return[fmt(start),fmt(end)]}
const blank=()=>({warehouse:'主仓库',count_type:'full',planRange:defaultRange(),responsible_id:null,participant_ids:[],difference_threshold:5,scope:{categories:[],abc_levels:[],product_ids:[],supplier_ids:[],near_expiry_only:false,near_expiry_days:7}})
const form=reactive(blank())
const averageAccuracy=computed(()=>rows.value.length?(rows.value.reduce((s,r)=>s+Number(r.accuracy_rate||0),0)/rows.value.length).toFixed(2):'100.00')
const loadCounts=async()=>rows.value=await getInventoryCounts({date_from:dateRange.value[0],date_to:dateRange.value[1],status:statusFilter.value||undefined})
const load=async()=>{Object.assign(options,await getWarehouseOptions());await loadCounts()}
const openCreate=()=>{Object.assign(form,blank());form.responsible_id=options.users[0]?.id||null;createVisible.value=true}
const create=async()=>{if(!form.responsible_id||!form.planRange?.length)return ElMessage.warning('请填写负责人和计划时间');saving.value=true;try{const row=await createInventoryCount({...form,planned_start:form.planRange[0],planned_end:form.planRange[1]});ElMessage.success(`盘点任务已生成，共${row.item_count}项`);createVisible.value=false;await loadCounts();await openDetail(row)}finally{saving.value=false}}
const hydrate=row=>({...row,actual_quantity:row.status==='recounting'?(row.recount_quantity??row.first_count_quantity):(row.final_quantity??row.first_count_quantity)})
const openDetail=async row=>{Object.assign(detail,await getInventoryCount(row.id));detail.items=detail.items.map(hydrate);selectedItems.value=[];detailVisible.value=true}
const saveEntries=async()=>{const items=detail.items.filter(i=>i.actual_quantity!==null&&i.actual_quantity!==undefined).map(i=>({id:i.id,actual_quantity:i.actual_quantity,batch_no:i.batch_no,production_date:i.production_date,shelf_life_days:i.shelf_life_days,difference_reason:i.difference_reason,reason_note:i.reason_note}));if(!items.length)return ElMessage.warning('请至少录入一项实盘数量');saving.value=true;try{Object.assign(detail,await saveInventoryCountEntries(detail.id,{items}));detail.items=detail.items.map(hydrate);ElMessage.success('盘点结果已保存');await loadCounts()}finally{saving.value=false}}
const recount=async()=>{await createInventoryRecount(detail.id,{item_ids:selectedItems.value.map(i=>i.id),assigned_user_ids:detail.participant_ids});ElMessage.success('已生成复盘任务');await openDetail(detail)}
const confirm=async()=>{await ElMessageBox.confirm('确认后将锁定盘点结果，并自动生成盘盈/盘亏仓库流水，是否继续？','确认盘点',{type:'warning'});const result=await confirmInventoryCount(detail.id);ElMessage.success(result.message);await openDetail(detail);await loadCounts()}
const saveBlob=(blob,name)=>{const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)}
const downloadTemplate=async()=>saveBlob(await downloadInventoryCountTemplate(detail.id),`${detail.count_no}-盘点录入模板.xlsx`)
const uploadCount=async({file})=>{const result=await importInventoryCount(detail.id,file);ElMessage.success(result.message);Object.assign(detail,result.count);detail.items=detail.items.map(hydrate);await loadCounts()}
const downloadReport=async row=>saveBlob(await exportInventoryCount(row.id),`${row.count_no}-盘点差异表.xlsx`)
const focusNext=e=>{const inputs=[...document.querySelectorAll('.actual-input input:not([disabled])')],index=inputs.indexOf(e.target);inputs[index+1]?.focus();inputs[index+1]?.select()}
const currentDifference=row=>row.actual_quantity==null?row.difference_quantity:Number(row.actual_quantity)-Number(row.system_quantity)
const differenceClass=row=>currentDifference(row)>0?'gain':currentDifference(row)<0?'danger':''
const number=v=>Number(v||0).toLocaleString('zh-CN',{maximumFractionDigits:4}),money=v=>Number(v||0).toFixed(2)
const typeName=v=>({full:'全仓',partial:'范围',cycle:'循环'})[v]||v,statusTag=v=>v==='confirmed'?'success':v==='recounting'?'warning':'primary'
const batchStatus=v=>({normal:'正常',near_expiry:'临期',expired:'过期',missing_expiry:'效期缺失'})[v]||v
onMounted(load)
</script>

<style scoped>
.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:16px 0}.metrics span,.metrics b{display:block}.metrics span{color:#7d899a}.metrics b{font-size:25px;margin-top:7px}.panel{margin-top:14px}.filters{display:flex;gap:10px;margin-bottom:14px}.detail-head{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:12px}.detail-head>div{display:flex;align-items:center;gap:9px}.hint{margin:0 8px 0 14px;color:#8490a3}.danger{color:#d94b4b}.warning{color:#d88624}.ok,.gain{color:#26966b}@media(max-width:1000px){.metrics{grid-template-columns:repeat(2,1fr)}.detail-head{align-items:flex-start;flex-direction:column}}
</style>
